import hashlib,json,pathlib
p=pathlib.Path('/protected/peer_handoff')
b=p.read_bytes()
print('bytes',len(b),'sha256',hashlib.sha256(b).hexdigest())
data=json.loads(b)
print('type',type(data).__name__)
if isinstance(data,dict):
 print('keys',list(data))
 def walk(o,pre=''):
  if isinstance(o,dict):
   for k,v in o.items():
    if k in ('files_sha256','files') and isinstance(v,dict):
     print(pre+k,'n',len(v))
    elif isinstance(v,(dict,list)):
     print(pre+k, type(v).__name__, (len(v) if hasattr(v,'__len__') else ''))
     if k not in ('files_sha256',):
      walk(v, pre+k+'.')
    else:
     s=str(v)
     print(pre+k, s[:300])
  elif isinstance(o,list):
   print(pre,'list',len(o))
   for i,v in enumerate(o[:8]):
    walk(v, pre+f'[{i}].')
 walk(data)
 # hashes
 man=None
 def find_map(o):
  global man
  if isinstance(o,dict):
   if 'files_sha256' in o and isinstance(o['files_sha256'],dict):
    return o
   for v in o.values():
    r=find_map(v)
    if r: return r
  return None
 man=find_map(data)
 print('MAP', bool(man))
 root=pathlib.Path('/workspace/source')
 if man:
  for n,exp in man['files_sha256'].items():
   if not (n.endswith('.py') or n.endswith('.c')):
    print('SKIP', n); continue
   fp=root/n
   if not fp.is_file():
    print('ABSENT', n); continue
   dig=hashlib.sha256(fp.read_bytes()).hexdigest()
   print(('MATCH' if dig==exp else 'DIFF'), n)
